CREATE OR REPLACE FUNCTION public.create_workspace(_org uuid,_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; lim integer; n int; BEGIN PERFORM 1 FROM public.organizations WHERE id=_org FOR UPDATE; IF NOT public.has_org_role(_org,'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; IF length(trim(_name)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Workspace name must contain 1 to 120 characters'; END IF; IF NOT EXISTS(SELECT 1 FROM public.subscriptions s JOIN public.plan_entitlements e ON e.plan_key=s.plan_key WHERE s.org_id=_org AND e.feature_key='workspaces' AND s.status IN ('active','trialing') AND (s.status<>'trialing' OR s.trial_ends_at>now())) THEN RAISE EXCEPTION 'Workspace entitlement not configured or plan inactive'; END IF; lim:=public.org_entitlement(_org,'workspaces'); SELECT count(*) INTO n FROM public.workspaces WHERE org_id=_org; IF lim IS NOT NULL AND n>=lim THEN RAISE EXCEPTION 'Your workspace limit has been reached'; END IF; INSERT INTO public.workspaces(org_id,name) VALUES(_org,trim(_name)) RETURNING id INTO wid; INSERT INTO public.business_profiles(org_id,workspace_id) VALUES(_org,wid); INSERT INTO public.audit_logs(org_id,actor_id,action,target_type,target_id) VALUES(_org,auth.uid(),'workspace.created','workspace',wid::text); RETURN wid; END $$;